from __future__ import annotations

__doc__ = """
Fortran-oriented ADAAs and coefficient backend definitions.

The current Fortran backend intentionally reuses NumPy-owned storage. This is a
special case: ``f2py`` can consume NumPy arrays directly, so the Fortran-facing
ADAA classes differ semantically from the generic NumPy ADAAs while sharing the
same host-memory implementation strategy.
"""

from typing import Any

import numpy as np

from ....adaa import ComplexArrayADAA, ImagArrayADAA, RealArrayADAA
from ..numpy.numpy_adaa import NumPyCoeffBackend


class FortranCoeffBackend(NumPyCoeffBackend):
    """Coefficient backend for Fortran wrappers using NumPy storage."""

    def coeff_new_array(self, size: int, dtype: str):
        return super().coeff_new_array(size=size, dtype=dtype)

    def coeff_from_numpy(
        self,
        coeff_like: Any,
        nparray: np.ndarray,
        size: int,
        dtype: str,
    ) -> None:
        return super().coeff_from_numpy(
            coeff_like=coeff_like,
            nparray=nparray,
            size=size,
            dtype=dtype,
        )

    def coeff_to_numpy(
        self, coeff_like: Any, size: int, dtype: str
    ) -> np.ndarray:
        return super().coeff_to_numpy(
            coeff_like=coeff_like, size=size, dtype=dtype
        )


class FortranCA(
    ComplexArrayADAA,
    backend=FortranCoeffBackend(),
    identifier="FORTRAN",
    is_anchor=True,
):
    """Complex ADAA intended for Fortran/f2py routine calls."""


class FortranRA(
    RealArrayADAA,
    backend=FortranCoeffBackend(),
    identifier="FORTRAN",
    is_anchor=True,
):
    """Real ADAA intended for Fortran/f2py routine calls."""


class FortranIA(
    ImagArrayADAA,
    backend=FortranCoeffBackend(),
    identifier="FORTRAN",
    is_anchor=True,
):
    """Purely imaginary ADAA intended for Fortran/f2py routine calls."""


__all__ = [
    "FortranCoeffBackend",
    "FortranCA",
    "FortranRA",
    "FortranIA",
]
